sys_variable_value.value:
(function execute(inputs, outputs) {

    var studentId = inputs.student;

    var evidence = {
        student: {},
        skills: [],
        assessments: [],
        applications: [],
        training: [],
        interviews: [],
        interview_feedback: [],
        placement_intelligence: {}
    };

    // --------------------------------------------------
    // 1. STUDENT MASTER
    // --------------------------------------------------

    var studentGR = new GlideRecord('x_snc_campus360_student_master');

    if (studentGR.get(studentId)) {

        evidence.student = {
            sys_id: studentGR.getUniqueValue(),
            student_id: studentGR.getValue('student_id'),
            student_name: studentGR.getValue('student_name'),
            email: studentGR.getValue('email'),
            degree: studentGR.getDisplayValue('degree'),
            branch: studentGR.getDisplayValue('branch'),
            batch: studentGR.getValue('batch'),
            cgpa: studentGR.getValue('cgpa'),
            backlogs: studentGR.getValue('backlogs'),
            placement_status: studentGR.getDisplayValue('placement_status'),
            profile_status: studentGR.getDisplayValue('profile_status')
        };
    }

    // --------------------------------------------------
    // 2. STUDENT SKILLS
    // --------------------------------------------------

    var skillGR = new GlideRecord('x_snc_campus360_student_skills');
    skillGR.addQuery('student', studentId);
    skillGR.query();

    while (skillGR.next()) {

        evidence.skills.push({
            skill_record_id: skillGR.getValue('skill_record_id'),
            skill_name: skillGR.getValue('skill_name'),
            skill_category: skillGR.getDisplayValue('skill_category'),
            assessment_score: skillGR.getValue('assessment_score'),
            certification: skillGR.getValue('certification'),
            last_assessed: skillGR.getValue('last_assessed'),
            skill_level: skillGR.getValue('skill_level')
        });
    }

    // --------------------------------------------------
    // 3. STUDENT ASSESSMENTS
    // --------------------------------------------------

    var assessmentGR = new GlideRecord('x_snc_campus360_student_assessment');
    assessmentGR.addQuery('student', studentId);
    assessmentGR.query();

    while (assessmentGR.next()) {

        evidence.assessments.push({
            assessment_id: assessmentGR.getValue('assessment_id'),
            assessment_name: assessmentGR.getValue('assessment_name'),
            assessment_type: assessmentGR.getDisplayValue('assessment_type'),
            maximum_score: assessmentGR.getValue('maximum_score'),
            assessment_date: assessmentGR.getValue('assessment_date'),
            result: assessmentGR.getValue('result'),
            opportunity: assessmentGR.getDisplayValue('opportunity')
        });
    }

    // --------------------------------------------------
    // 4. STUDENT APPLICATIONS
    // --------------------------------------------------

    var applicationGR = new GlideRecord('x_snc_campus360_student_application');
    applicationGR.addQuery('student', studentId);
    applicationGR.query();

    while (applicationGR.next()) {

        evidence.applications.push({
            application_id: applicationGR.getValue('application_id'),
            opportunity: applicationGR.getDisplayValue('opportunity'),
            application_status: applicationGR.getDisplayValue('application_status'),
            student_response: applicationGR.getDisplayValue('student_response'),
            applied_date: applicationGR.getValue('applied_date'),
            shortlisted: applicationGR.getValue('shortlisted'),
            assessment_status: applicationGR.getDisplayValue('assessment_status'),
            interview_status: applicationGR.getDisplayValue('interview_status'),
            offer_status: applicationGR.getDisplayValue('offer_status'),
            reminder_count: applicationGR.getValue('reminder_count'),
            ai_match_score: applicationGR.getValue('ai_match_score')
        });
    }

    // --------------------------------------------------
    // 5. TRAINING ENROLLMENT
    // --------------------------------------------------

    var trainingGR = new GlideRecord('x_snc_campus360_training_enrollment');
    trainingGR.addQuery('student', studentId);
    trainingGR.query();

    while (trainingGR.next()) {

        evidence.training.push({
            enrollment_id: trainingGR.getValue('enrollment_id'),
            training_program: trainingGR.getDisplayValue('training_program'),
            attendance: trainingGR.getValue('attendance'),
            completion_status: trainingGR.getDisplayValue('completion_status')
        });
    }

    // --------------------------------------------------
    // 6. MOCK INTERVIEWS
    // --------------------------------------------------

    var interviewGR = new GlideRecord('x_snc_campus360_mock_interview');
    interviewGR.addQuery('student', studentId);
    interviewGR.query();

    while (interviewGR.next()) {

        evidence.interviews.push({
            interview_id: interviewGR.getValue('interview_id'),
            trainer: interviewGR.getDisplayValue('trainer'),
            interview_type: interviewGR.getDisplayValue('interview_type'),
            interview_date: interviewGR.getValue('interview_date'),
            start_time: interviewGR.getValue('start_time'),
            end_time: interviewGR.getValue('end_time'),
            qr_status: interviewGR.getDisplayValue('qr_status'),
            interview_status: interviewGR.getDisplayValue('interview_status')
        });
    }

    // --------------------------------------------------
    // 7. INTERVIEW FEEDBACK
    // --------------------------------------------------

    var feedbackGR = new GlideRecord('x_snc_campus360_interview_feedback');
    feedbackGR.addQuery('student', studentId);
    feedbackGR.query();

    while (feedbackGR.next()) {

        evidence.interview_feedback.push({
            feedback_id: feedbackGR.getValue('feedback_id'),
            interview: feedbackGR.getDisplayValue('interview'),
            trainer: feedbackGR.getDisplayValue('trainer'),
            technical_score: feedbackGR.getValue('technical_score'),
            communication_score: feedbackGR.getValue('communication_score'),
            problem_solving_score: feedbackGR.getValue('problem_solving_score'),
            overall_score: feedbackGR.getValue('overall_score'),
            strengths: feedbackGR.getValue('strengths'),
            improvement_areas: feedbackGR.getValue('improvement_areas'),
            recommendation: feedbackGR.getValue('recommendation'),
            feedback_date: feedbackGR.getValue('feedback_date')
        });
    }

    // --------------------------------------------------
    // 8. PLACEMENT INTELLIGENCE
    // --------------------------------------------------

    var intelligenceGR = new GlideRecord('x_snc_campus360_placement_intelligence');
    intelligenceGR.addQuery('student', studentId);
    intelligenceGR.orderByDesc('last_updated');
    intelligenceGR.setLimit(1);
    intelligenceGR.query();

    if (intelligenceGR.next()) {

        evidence.placement_intelligence = {
            intelligence_id: intelligenceGR.getValue('intelligence_id'),
            risk_level: intelligenceGR.getDisplayValue('risk_level'),
            readiness_score: intelligenceGR.getValue('readiness_score'),
            participation_score: intelligenceGR.getValue('participation_score'),
            missed_opportunities: intelligenceGR.getValue('missed_opportunities'),
            primary_skill_gap: intelligenceGR.getDisplayValue('primary_skill_gap'),
            ai_insight: intelligenceGR.getValue('ai_insight'),
            last_updated: intelligenceGR.getValue('last_updated')
        };
    }

    // --------------------------------------------------
    // RETURN ALL EVIDENCE AS STRING
    // --------------------------------------------------

    outputs.placement_evidence = JSON.stringify(evidence);

})(inputs, outputs);

